"""Alembic's start-up script, run by every `alembic` command (generated by Alembic, then adapted).

It takes the database URL from our settings (DATABASE_URL), connects, and runs the migrations.
- target_metadata = our models, so `alembic revision --autogenerate` can compare the models with
  the database and draft a migration for you (always read the draft before applying it).
- include_object() makes autogenerate ignore LangGraph's checkpoint tables: they exist in the
  database but not in our models, and it would otherwise propose to drop them.
- "Offline" mode prints the SQL instead of running it; "online" (the normal case) runs it.
"""

from logging.config import fileConfig

from alembic import context
from sqlalchemy import engine_from_config, pool

from app.config import get_settings
from app.db.models import Base

config = context.config
config.set_main_option("sqlalchemy.url", get_settings().database_url)

if config.config_file_name is not None:
    fileConfig(config.config_file_name)

target_metadata = Base.metadata


def include_object(obj, name, type_, reflected, compare_to):
    """Ignore tables that exist in the DB but not in our models (LangGraph checkpointer)."""
    if type_ == "table" and reflected and compare_to is None:
        return False
    return True


def run_migrations_offline() -> None:
    context.configure(
        url=config.get_main_option("sqlalchemy.url"),
        target_metadata=target_metadata,
        literal_binds=True,
    )
    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    connectable = engine_from_config(
        config.get_section(config.config_ini_section, {}),
        prefix="sqlalchemy.",
        poolclass=pool.NullPool,
    )
    with connectable.connect() as connection:
        context.configure(
            connection=connection,
            target_metadata=target_metadata,
            include_object=include_object,
        )
        with context.begin_transaction():
            context.run_migrations()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
